<?php
require_once __DIR__.'/includes/functions.php'; exigir_login();$titulo='Extratos';$conta=tipo_usuario()==='cliente'?conta_cliente_atual():trim($_GET['conta']??'');$erro='';$dados=null;$lista=null;
if($conta!==''){if(tipo_usuario()==='cliente'&&$conta!==conta_cliente_atual()){$erro='Você só pode consultar sua própria conta.';$conta=conta_cliente_atual();}$stmt=mysqli_prepare($conexao,'SELECT conta, agencia, cliente FROM tbcontas WHERE conta=? LIMIT 1');mysqli_stmt_bind_param($stmt,'s',$conta);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);$dados=mysqli_fetch_assoc($r);mysqli_stmt_close($stmt);if($dados){$stmt=mysqli_prepare($conexao,'SELECT data_lanc, valor, tipo FROM tblancamentos WHERE conta=? ORDER BY data_lanc DESC');mysqli_stmt_bind_param($stmt,'s',$conta);mysqli_stmt_execute($stmt);$lista=mysqli_stmt_get_result($stmt);}else $erro='Conta não encontrada.';}
include __DIR__.'/includes/header.php'; ?>
<div class="cabecalho-pagina"><div><span class="etiqueta">HISTÓRICO</span><h1>Extratos</h1><p>Consulte as movimentações de uma conta bancária.</p></div></div><?php if($erro): ?><div class="alerta"><?=e($erro)?></div><?php endif; ?><?php if(tipo_usuario()!=='cliente'): ?><section class="painel"><form method="get" class="busca"><div class="busca-campo"><label>Número da conta</label><input name="conta" value="<?=e($conta)?>" required></div><button class="botao botao-principal">Consultar extrato</button></form></section><?php endif; ?><?php if($dados): ?><section class="cartao-saldo margem-topo"><div><span>Extrato da conta</span><h2><?=e($dados['cliente'])?></h2><p>Conta <?=e($dados['conta'])?> · Agência <?=e($dados['agencia'])?></p></div><div><small>Saldo atual</small><strong class="saldo-menor"><?=dinheiro(saldo_conta($dados['conta']))?></strong></div></section><section class="painel margem-topo"><h2>Movimentações</h2><div class="tabela-responsiva"><table><thead><tr><th>Data</th><th>Descrição</th><th>Entrada</th><th>Saída</th></tr></thead><tbody><?php $tem=false;if($lista):while($l=mysqli_fetch_assoc($lista)):$tem=true; ?><tr><td><?=e(date('d/m/Y',strtotime($l['data_lanc'])))?></td><td><?= $l['tipo']==='D'?'Depósito':'Saque' ?></td><td class="texto-positivo"><?=$l['tipo']==='D'?dinheiro($l['valor']):'—'?></td><td class="texto-negativo"><?=$l['tipo']==='S'?dinheiro($l['valor']):'—'?></td></tr><?php endwhile;endif;if(!$tem): ?><tr><td colspan="4" class="vazio">Nenhuma movimentação encontrada para esta conta.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?><?php include __DIR__.'/includes/footer.php'; ?>
